<script setup lang="ts">import { ref } from 'vue';import { api } from '../../api';import CitationList from '../../components/common/CitationList.vue';import ConfidenceBadge from '../../components/common/ConfidenceBadge.vue';const q=ref('620分能报哪些专业？');const messages=ref<any[]>([]);const history=ref<any[]>([]);const loading=ref(false);async function ask(){loading.value=true;const r=await api.ask({question:q.value,session_id:'session-demo',province:'河南'});messages.value.push({question:q.value,...r});q.value='';loading.value=false}async function loadHistory(){history.value=(await api.qaHistory({session_id:'session-demo'})).items}</script><template><section class="content-page"><div class="eyebrow">KNOWLEDGE / QA</div><h1>政策问答</h1><div class="ask-row"><input v-model="q" @keyup.enter="ask" placeholder="输入问题"/><button class="primary" :disabled="loading" @click="ask">{{loading?'整理中…':'提问 ↗'}}</button><button class="text-btn" @click="loadHistory">查看历史</button></div><div v-for="m in messages" :key="m.qa_log_id" class="answer-card"><p class="muted">问题：{{m.question}}</p><ConfidenceBadge :level="m.confidence_level"/><p>{{m.answer}}</p><p v-if="m.needs_review||m.degraded" class="muted">该回答需要人工核验或已使用降级结果。</p><CitationList :citations="m.citations"/></div><div v-for="h in history" :key="h.qa_log_id" class="state-box">{{h.question||'历史问答'}} · {{h.answer}}</div></section></template>
